import {membraneLesson,leadLesson} from './base-lessons.js';
const link=(url,title)=>`<a href="${url}" target="_blank" rel="noopener">${title} ↗</a>`;
export const waveEvidence=`<details class="wave-evidence-details"><summary><span><strong>Evidence behind the wave</strong><small>Human recordings · causal experiment · 3D simulation</small></span><span class="details-indicator" aria-hidden="true">+</span></summary><div class="wave-evidence-body"><div class="evidence-heading"><span class="eyebrow">THE EVIDENCE BEHIND THE WAVE</span><h2>What is demonstrated, and where.</h2><p>The polarity mechanism is reproducible. A universal reversed recovery sequence across the human heart is not established.</p></div><div class="evidence-grid"><article><span class="evidence-tag">CAUSAL EXPERIMENT · 7 DOGS</span><h3>Change local AP duration, change the T wave.</h3><p>Higuchi & Nakaya warmed and cooled the epicardium while recording epicardial and endocardial monophasic action potentials plus a local electrogram. Altering the AP-duration difference changed T-wave polarity.</p>${link('https://pubmed.ncbi.nlm.nih.gov/6464965/','Higuchi & Nakaya, 1984')}</article><article><span class="evidence-tag">DIRECT OPTICAL RECORDINGS · 10 HUMAN WEDGES</span><h3>Later activation can still finish earlier.</h3><p>Boukens et al. reported subendocardial APD 360 ± 17 ms and recovery 364 ± 16 ms, versus subepicardial APD 317 ± 20 ms and recovery 349 ± 19 ms. Recovery was only mildly reversed and largely synchronized.</p>${link('https://pmc.ncbi.nlm.nih.gov/articles/PMC4571834/','Boukens et al., 2015')}</article><article><span class="evidence-tag">PUBLISHED 3D FORWARD SIMULATION</span><h3>The entire spatial pattern matters.</h3><p>The same study used the ten Tusscher ventricular cell model, CARP tissue propagation and a current-based pseudo-ECG. Reversing the stimulation site did not simply reverse the T wave. The three-dimensional recovery pattern matters.</p>${link('https://pmc.ncbi.nlm.nih.gov/articles/PMC4571834/#sec5','Boukens et al., Figures 5–6')}</article></div><p class="evidence-caveat">The interactive strand is a transparent reduced forward calculation. The “human wedge timings” preset interpolates published endpoint means; its intermediate cells and AP shapes are simulated. In three intact isolated human hearts, full-wall electrogram-derived recovery did not follow a universal reversed activation sequence. ${link('https://pubmed.ncbi.nlm.nih.gov/27737802/','Opthof et al., 2017')}</p></div></details>`;
export const heartEvidence=`<div class="evidence-heading"><span class="eyebrow">HUMAN DATA → CALIBRATED SOURCES → CALCULATED ECG</span><h2>Improve the sources. Recalculate the signal.</h2><p>Real anatomy and human optical recordings inform the model. A measured lead II guides its parameter fit.</p></div><div class="evidence-grid"><article><span class="evidence-tag">ANATOMY + EXPLICIT RECONSTRUCTION</span><h3>The missing appendage is now connected.</h3><p>The CT-derived mean preserves the thick LV wall. The source’s fifth LA opening is its cropped appendage ostium, distinct from four pulmonary veins. A blind-ending, inferred LAA adds 9,824 mesh nodes and participates in the electrical calculation.</p>${link('https://zenodo.org/records/4593739','Rodero anatomy · CC BY 4.0')}<br>${link('./data/left-atrial-appendage.json','Appendage provenance & checks')}</article><article><span class="evidence-tag">2,948 OPTICAL SITES · TWO HUMAN PREPARATIONS</span><h3>A pooled cellular recovery shape.</h3><p>Accepted human optical signals are aligned and duration-normalized only to estimate a robust AP shape, with equal donor weighting. Atrial APs use the Courtemanche ionic model. Local durations, intrinsic ventricular upstroke and absolute voltage scale remain model assumptions.</p>${link('./data/pooled-human-ventricular-template.json','Pooled waveform & original-file hashes')}<br>${link('https://zenodo.org/records/3986725','Original human recordings · CC0')}</article><article><span class="evidence-tag">MEASURED CALIBRATION TARGET</span><h3>Fifteen delivery sites. One computed field.</h3><p>A 108-beat PTB healthy-control median guides activation timing, effective source conductivity and recovery durations. Basal RV delivery removes the late QRS shoulder. All twelve leads still come from the same spatial source integral; the finished ECG is not filtered.</p>${link('./data/lead-ii-fit-comparison.png','Compare the fitting methods')}<br>${link('./data/lead-ii-fit-study.json','Fit metrics, parameters & alternatives')}</article></div><p class="evidence-caveat">The reference is used in calibration, so agreement is not an independent validation. The anatomy, optical recordings and EKG come from different people. A lead-II fit does not uniquely recover true activation, recovery or conductivity, and other leads are not optimized; 10 of the 11 other leads match this same recording less closely. Dense sampling uses 2.40 million voltage sites while holding the activation graph fixed. ${link('./data/FOUR_CHAMBER_METHODS.md','Complete equations & limitations')} · ${link('./data/heart-model-reproducible-source.zip','Reproduce the model')}</p>`;
function waveLesson(s){
  const human=s.wavePreset==='human';
  return `<div class="lesson-kicker">02 / THE WAVE</div><h2>Recovery order<br>is a timing problem.</h2>
  <div class="segmented wave-mode"><button class="seg-btn ${human?'active':''}" data-wave-mode="human">Human timings</button><button class="seg-btn ${!human?'active':''}" data-wave-mode="explore">Explore simulation</button></div>
  <div class="provenance-badge ${human?'measured':'modeled'}"><i></i>${human?'HUMAN TIMINGS · SIMULATED STRAND':'EXPLORATORY SIMULATION'}</div>
  <p class="lesson-intro wave-intro">${human?'A shorter action potential can let a later-activated cell recover first.':'Keep activation fixed. Change AP duration to change recovery order.'}</p>
  <button id="microscopy-open" class="microscopy-open microscopy-card" aria-haspopup="dialog" aria-controls="microscopy-dialog"><img src="./assets/microscopy/cardiac-muscle-light-200x.jpg" alt="" width="3264" height="1840" decoding="async"><span class="microscopy-card-copy"><strong>See real microscopy</strong><small>Muscle cells · junctions · Purkinje</small></span><span class="microscopy-card-arrow" aria-hidden="true">↗</span></button>
  <div class="formula-card"><div class="formula-label">RECOVERY = ACTIVATION + DURATION</div><div class="formula">RT = AT + APD</div><div class="formula-desc" id="wave-equation">Human endpoints: ΔRT = 28 − 43 = −15 ms</div></div>
  <div class="now-card wave-now"><div class="now-label"><i></i><span id="now-title"></span></div><p class="now-copy" id="now-copy"></p></div>
  <div class="control-block wave-controls">${human?'':`<label class="control-label" for="shortening">APD SHORTENING <strong id="shortening-value">${s.shortening} ms</strong></label><input id="shortening" type="range" min="0" max="100" step="1" value="${s.shortening}"><div class="segmented three"><button class="seg-btn" data-shortening="0">Same order</button><button class="seg-btn" data-shortening="40">Together</button><button class="seg-btn" data-shortening="60">Reverse</button></div><div class="control-label map-label">VIRTUAL ELECTRODES</div><div class="segmented"><button class="seg-btn ${s.waveGeometry==='distant'?'active':''}" data-wave-geometry="distant">Distant</button><button class="seg-btn ${s.waveGeometry==='near'?'active':''}" data-wave-geometry="near">Near the ends</button></div><label class="toggle-row">Add an early AP notch<input type="checkbox" class="toggle" id="wave-notch" ${s.waveNotch?'checked':''}></label>`}
  <label class="toggle-row">Show current loops<input type="checkbox" class="toggle" id="currents-toggle" ${s.showCurrents?'checked':''}></label><div class="current-display-controls"><div class="segmented"><button class="seg-btn ${s.currentDisplay!=='strength'?'active':''}" data-current-display="direction" aria-pressed="${s.currentDisplay!=='strength'}">Direction</button><button class="seg-btn ${s.currentDisplay==='strength'?'active':''}" data-current-display="strength" aria-pressed="${s.currentDisplay==='strength'}">Scaled strength</button></div><p>Direction view enlarges weak arrows; values stay unchanged.</p></div>
  <details class="wave-model-details"><summary>${human?'Human data & model details':'Model details & controls'}</summary>${human?`<div class="human-timing-note"><strong>10 human LV wedges · APD₈₀</strong><span>Inner wall: 360 ms · Outer wall: 317 ms</span>${link('https://pmc.ncbi.nlm.nih.gov/articles/PMC4571834/','Boukens et al., 2015')}</div><p>The strand interpolates published endpoint means. Intermediate cells, AP shapes and external voltage are simulated. Distant virtual electrodes reduce end weighting.</p>`:`<p>Nearby electrodes weight an approaching wave more strongly. The voltage scale stays fixed; the plot axis adjusts. The optional early notch is an imposed AP feature.</p>`}<label class="toggle-row">Make every cell’s voltage identical<input type="checkbox" class="toggle" id="uniform-toggle" ${s.uniform?'checked':''}></label><p>Module 2 represents working ventricular muscle. Its rows simplify a branching network of coupled cells.</p><div class="data-links">${link('./data/WAVE_MODEL_NOTES.md','Equations, sources & checks')}</div></details></div>`;
}
function heartLesson(s){
  const measured=s.heartMode==='measured';
  const leadOptions=['I','II','III','aVR','aVL','aVF','V1','V2','V3','V4','V5','V6'].map(l=>`<option value="${l}" ${s.heartLead===l?'selected':''}>Lead ${l}</option>`).join('');
  const timingOptions=[['heterogeneous','Calibrated cellular model'],['equal_apd','Equal ventricular APD₉₀'],['optical_duration','Original optical-donor AP']].map(([v,t])=>`<option value="${v}" ${s.modelVariant===v?'selected':''}>${t}</option>`).join('');
  return `<div class="lesson-kicker">04 / THE WHOLE HEART</div>
  <h2>${measured?'Real recordings.<br>A shared clock.':'Four chambers.<br>One lead’s voltage.'}</h2>
  <div class="segmented heart-mode"><button class="seg-btn ${measured?'active':''}" data-heart-mode="measured">Human recordings</button><button class="seg-btn ${!measured?'active':''}" data-heart-mode="model">3D heart model</button></div>
  ${measured?'':`<div class="heart-surface-controls"><div class="control-label">HEART VIEW <button class="view-reset-link" id="view-reset" type="button">Reset view ↺</button></div><div class="segmented heart-surface-switch" role="group" aria-label="Heart surface view"><button class="seg-btn ${s.cutaway?'active':''}" data-heart-surface="cutaway" aria-pressed="${s.cutaway}"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M12 3 4 7.5v9L12 21V3Zm0 0 8 4.5v9L12 21M4 7.5l8 4.5 8-4.5"/></svg>Cutaway</button><button class="seg-btn ${!s.cutaway?'active':''}" data-heart-surface="full" aria-pressed="${!s.cutaway}"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="m12 3-8 4.5v9l8 4.5 8-4.5v-9L12 3Zm0 9v9M4 7.5l8 4.5 8-4.5"/></svg>Full surface</button></div><details class="appendage-options"><summary>Appendage</summary><label class="toggle-row">Show reconstructed appendage<input type="checkbox" class="toggle" id="appendage-toggle" ${s.showAppendage!==false?'checked':''}></label><div class="appendage-options-foot"><button class="appendage-inspect" id="appendage-inspect" type="button">Inspect appendage ↗</button><small>Visibility only · ECG unchanged</small></div></details></div>`}
  <p class="lesson-intro heart-intro">${measured?'Inspect measured action potentials across a human ventricular wall. Click several locations to overlay their signals on one shared time axis.':'Follow atrial activation, AV delay, and the ventricular wave through CT-derived anatomy. The EKG is calculated from this spatial voltage field.'}</p>
  <div class="provenance-badge ${measured?'measured':'modeled'}"><i></i>${measured?'EXPERIMENT · HUMAN LV WEDGE':'CT ANATOMY · CALIBRATED SIMULATION'}</div>
  <div class="control-block heart-controls">
  ${measured?`<label class="control-label" for="donor">CHOOSE A HUMAN PREPARATION</label><select class="wide-select" id="donor"><option value="1" ${s.donor===1?'selected':''}>Donor 1 · 2,493 accepted sites</option><option value="2" ${s.donor===2?'selected':''}>Donor 2 · 455 accepted sites</option></select>`:`<label class="control-label" for="heart-lead">CHOOSE AN EKG LEAD</label><select class="wide-select" id="heart-lead">${leadOptions}</select><p class="experiment-hint">Calibrated to lead II. The other leads are exploratory.</p><label class="toggle-row lead-axis-control" title="Negative reference → positive electrode, projected through the heart. This is a geometric guide; the calculated lead field varies in space.">Show lead axis<input type="checkbox" class="toggle" id="lead-axis-toggle" ${s.showLeadAxis?'checked':''}></label><div class="segmented three heart-phase-buttons">${[['p','P · atria'],['qrs','QRS'],['t','T · recovery']].map(([v,t])=>`<button class="seg-btn" data-heart-phase="${v}">${t}</button>`).join('')}</div>`}
  <div class="control-label map-label">COLOR THE TISSUE BY</div><div class="segmented four">${[['voltage','Voltage'],['activation','AT'],['recovery','RT'],['apd','APD']].map(([k,t])=>`<button class="seg-btn ${s.heartMap===k?'active':''}" data-heart-map="${k}">${t}</button>`).join('')}</div>
  ${measured?`<label class="toggle-row">Inspect one beat instead of the average<input type="checkbox" class="toggle" id="single-beat" ${s.singleBeat?'checked':''}></label><div class="data-facts"><div><strong>1,000 Hz</strong><span>native recording</span></div><div><strong>4 beats</strong><span>default ensemble</span></div><div><strong>Relative</strong><span>optical amplitude</span></div></div><p class="data-boundary">No simultaneous EKG is supplied with these recordings. The separate 3D model computes an EKG.</p>`:`
  <div class="control-label map-label">WHICH TISSUE CONTRIBUTES TO THE EKG?</div><div class="segmented three">${[['total','Whole heart'],['atrial','Atria'],['ventricular','Ventricles']].map(([v,t])=>`<button class="seg-btn ${s.heartECGComponent===v?'active':''}" data-ecg-component="${v}">${t}</button>`).join('')}</div>
  <label class="toggle-row">Overlay measured calibration target<input type="checkbox" class="toggle" id="ecg-reference" ${s.showECGReference?'checked':''}></label><p class="reference-note" id="reference-note" ${s.showECGReference?'':'hidden'}>Gold dashed: PTB healthy control, 108-beat median. This recording guides the parameter fit; its original mV and time scale are retained.</p>
  <details class="model-experiments"><summary>Timing & numerical fidelity</summary><p class="experiment-hint">Activation, cellular recovery and effective tissue conductivities are calibrated to lead II. The displayed signal is still calculated from the 3D voltage field. A closer fit does not uniquely identify a real heart’s parameters.</p>
  <label class="control-label" for="heart-timing">CELLULAR RECOVERY MODEL</label><select id="heart-timing" class="wide-select">${timingOptions}</select><p class="experiment-hint" id="timing-note">Compare the calibrated AP family with equal durations or the original human optical-donor shape and duration.</p>
  <label class="control-label map-label" for="heart-resolution">COMPARE SOURCE SAMPLING</label><select id="heart-resolution" class="wide-select"><option value="native" ${s.heartResolution==='native'?'selected':''}>Refined source field</option><option value="original" ${s.heartResolution==='original'?'selected':''}>Original mesh nodes</option><option value="bin2" ${s.heartResolution==='bin2'?'selected':''}>2 mm source bins</option><option value="bin4" ${s.heartResolution==='bin4'?'selected':''}>4 mm source bins</option></select><p class="experiment-hint" id="sampling-note">Dense midpoint sampling resolves the voltage front between the original activation nodes. It does not add measured cells.</p>
  <div class="data-links fit-data-links">${link('./data/lead-ii-fit-comparison.png','Compare the fitting methods')}${link('./data/LEAD_II_CALIBRATION.md','Methods & all-lead comparison')}${link('./data/lead-ii-fit-study.json','Parameters & numerical results')}</div><p class="experiment-hint">The extra LA opening in the source is the cropped appendage ostium. A connected, blind-ending reconstruction now extends it. The four pulmonary veins remain open; the added shape is inferred.</p><label class="toggle-row">Show anatomical reference points<input type="checkbox" class="toggle" id="sample-points" ${s.showSamples?'checked':''}></label><label class="toggle-row">Make Vₘ identical everywhere<input type="checkbox" class="toggle" id="uniform-heart" ${s.uniformHeart?'checked':''}></label></details>
  <p class="experiment-hint">Drag to rotate. Click tissue to add or remove an AP. The cutaway exposes actual muscle thickness.</p>`}</div>
  <div class="comparison-controls"><div class="control-label">COMPARE ACTION POTENTIALS <strong id="selection-count">0 / 6</strong></div><p class="selection-help">Up to six sites, on the same time axis.</p><div id="site-chips" class="site-chips" aria-label="Selected comparison sites"></div><div class="secondary-controls"><button class="experiment-button" id="compare-open">Enlarge comparison ↗</button><button class="experiment-button" id="sites-clear">Clear sites</button></div></div>
  <div class="now-card heart-now"><div class="now-label"><i></i><span id="now-title"></span></div><p class="now-copy" id="now-copy"></p></div><div class="data-links">${measured?`${link(`./data/human/donor${s.donor}-metadata.json`,'Recording & processing')}${link('https://zenodo.org/records/3986725','Original data')}`:link('./data/FOUR_CHAMBER_METHODS.md','Model, data & fidelity')}</div>`;
}
export function getLesson(s){return [membraneLesson,waveLesson(s),leadLesson,heartLesson(s)][s.chapter];}
